<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
$user=require_login();
$q=db()->prepare("SELECT b.id,b.amount_cents,b.placed_at,i.id AS item_id,i.lot_number,i.title AS item_title,a.title AS auction_title,a.status AS auction_status,a.ends_at,(SELECT b2.amount_cents FROM bids b2 WHERE b2.auction_item_id=i.id ORDER BY b2.amount_cents DESC,b2.placed_at ASC,b2.id ASC LIMIT 1) AS high_amount,(SELECT b2.bidder_user_id FROM bids b2 WHERE b2.auction_item_id=i.id ORDER BY b2.amount_cents DESC,b2.placed_at ASC,b2.id ASC LIMIT 1) AS high_bidder_id,r.result_status,r.winner_user_id FROM bids b JOIN auction_items i ON i.id=b.auction_item_id JOIN auctions a ON a.id=i.auction_id LEFT JOIN auction_item_results r ON r.auction_item_id=i.id WHERE b.bidder_user_id=:uid ORDER BY b.placed_at DESC,b.id DESC");
$q->execute(['uid'=>$user['id']]);$bids=$q->fetchAll();
require dirname(__DIR__).'/app/layout.php';render_page_start('My bids','my-bids',$user);
?>
<section class="welcome"><div><p class="eyebrow">YOUR ACTIVITY</p><h1>My bids</h1><p class="muted">Your personal bid history and item status. Other bidders' identities are never shown here.</p></div><div class="welcome-icon">↗</div></section>
<div class="notice"><span class="notice-dot"></span><div><strong>Your bid activity</strong><p>Accepted bids are listed below. A bid can be overtaken before the auction closes; only the finalised result determines the winner.</p></div></div>
<section class="content-panel"><div class="section-heading"><div><p class="eyebrow">BID HISTORY</p><h2>Your bids</h2></div><span class="status-pill"><?= count($bids) ?> records</span></div><?php if(!$bids): ?><div class="empty-state"><strong>You have not placed any bids</strong><p>When live bidding is enabled, accepted bids will appear here.</p><a class="button button-primary" href="<?= e(app_url('auctions.php')) ?>">Browse catalogue →</a></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Item</th><th>Auction</th><th>Your bid</th><th>Current high bid</th><th>Bid position / result</th><th>Time placed</th><th>Auction status</th></tr></thead><tbody><?php foreach($bids as $b): ?><tr><td><strong><?= e($b['item_title']) ?></strong><small class="table-sub">Lot <?= e($b['lot_number']) ?></small></td><td><?= e($b['auction_title']) ?></td><td>N$ <?= number_format((int)$b['amount_cents']/100,2,'.',',') ?></td><td>N$ <?= number_format((int)$b['high_amount']/100,2,'.',',') ?></td><td><?php if($b['auction_status']==='closed'): ?><?= (int)$b['winner_user_id']===(int)$user['id']?'Winner':'Closed' ?><?php elseif((int)$b['high_bidder_id']===(int)$user['id']): ?>Leading<?php else: ?>Outbid<?php endif; ?></td><td><?= e($b['placed_at']) ?></td><td><span class="status-pill"><?= e(ucfirst($b['auction_status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php render_page_end(); ?>